// Alias the reprap_gcode plugin as "gcode", so that
// users can highlight with Prism.languages.gcode and
// <code class="language-gcode">…</code>.
if (Prism && Prism.languages && Prism.languages.reprap_gcode) {
	if (!Prism.languages.gcode) {
		Prism.languages.gcode = Prism.languages.reprap_gcode;
	}
}
